* { box-sizing: border-box; }
body { margin: 0; background: #f5f7fb; color: #172033; font: 16px/1.5 system-ui, sans-serif; }
.container { width: min(680px, calc(100% - 32px)); margin: 56px auto; padding: 32px; background: white; border: 1px solid #e2e7f0; border-radius: 12px; box-shadow: 0 8px 24px #1720330a; }
h1 { margin: 0 0 24px; font-size: 2rem; }
form { display: grid; gap: 8px; margin-bottom: 28px; }
input, button { min-height: 42px; padding: 8px 12px; border-radius: 6px; font: inherit; }
input { border: 1px solid #aeb8c9; }
button { width: fit-content; border: 0; background: #315ad5; color: white; cursor: pointer; }
button:hover { background: #2448b4; }
button:focus-visible, input:focus-visible { outline: 3px solid #8aa6ff; outline-offset: 2px; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 14px 0; border-top: 1px solid #e5e9f0; }
.alert { color: #b42318; margin: 4px 0; }
[hidden] { display: none !important; }

